"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[6059],{1683(e,t,n){n.r(t),n.d(t,{assets:()=>d,contentTitle:()=>l,default:()=>p,frontMatter:()=>c,metadata:()=>i,toc:()=>h});const i=JSON.parse('{"id":"part2-backend-platform-security/authentication-deep-dive","title":"Authentication: API Keys, Bearer Tokens, OAuth/OIDC, JWTs, and Opaque Tokens","description":"A practical, end-to-end guide to: API keys, Bearer tokens, OAuth/OIDC (PKCE), JWT vs opaque tokens (introspection), Google (Gmail) login verification with JWKS, and how this ties into MCP servers and SQL Server access.","source":"@site/docs/part2-backend-platform-security/09-authentication-deep-dive.mdx","sourceDirName":"part2-backend-platform-security","slug":"/part2-backend-platform-security/09-authentication-deep-dive","permalink":"/tutorials/part2-backend-platform-security/09-authentication-deep-dive","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":9,"frontMatter":{"title":"Authentication: API Keys, Bearer Tokens, OAuth/OIDC, JWTs, and Opaque Tokens","slug":"/part2-backend-platform-security/09-authentication-deep-dive","description":"A practical, end-to-end guide to: API keys, Bearer tokens, OAuth/OIDC (PKCE), JWT vs opaque tokens (introspection), Google (Gmail) login verification with JWKS, and how this ties into MCP servers and SQL Server access.","sidebar_label":"10. Authentication deep dive","pagination_label":"10. Authentication deep dive","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"9. First login and user provisioning","permalink":"/tutorials/part2-backend-platform-security/08-registering-new-users"},"next":{"title":"11. Passkeys, DPoP, mTLS, and token exchange","permalink":"/tutorials/part2-backend-platform-security/15-modern-auth-additions"}}');var o=n(4848),r=n(8453),s=n(8172);const a=JSON.parse('{"sourcePath":"part2-backend-platform-security/09-authentication-deep-dive.html","route":"/part2-backend-platform-security/09-authentication-deep-dive","kind":"chapter","partId":"part2","partLabel":"Part II - Backend, Platform & Security","accent":"teal","heading":"Authentication: Tokens, OAuth, and API Security","title":"Authentication: API Keys, Bearer Tokens, OAuth/OIDC, JWTs, and Opaque Tokens","description":"A practical, end-to-end guide to: API keys, Bearer tokens, OAuth/OIDC (PKCE), JWT vs opaque tokens (introspection), Google (Gmail) login verification with JWKS, and how this ties into MCP servers and SQL Server access.","readingMinutes":8,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-big-picture-who-talks-to-whom","label":"1) Big picture: who talks to whom?"},{"id":"2-bearer-tokens-authorization-bearer","label":"2) Bearer tokens (Authorization: Bearer ...)"},{"id":"3-api-keys-when-they-fit-and-when-they-don-t","label":"3) API keys: when they fit (and when they don\u2019t)"},{"id":"4-opaque-vs-jwt-access-tokens","label":"4) Opaque vs JWT access tokens"},{"id":"5-opaque-tokens-introspection-flow-client-server-both-talk-to-auth-server","label":"5) Opaque tokens: introspection flow (client + server both talk to auth server)"},{"id":"6-jwt-tokens-jwks-public-key-caching-server-keeps-the-public-key","label":"6) JWT tokens: JWKS + public key caching (server \u201ckeeps the public key\u201d)"},{"id":"7-gmail-authenticator-google-oidc-login-client-still-talks-to-google","label":"7) \u201cGmail authenticator\u201d: Google OIDC login (client still talks to Google)"},{"id":"8-pkce-why-it-exists-and-when-you-use-it","label":"8) PKCE: why it exists and when you use it"},{"id":"9-why-an-authorize-endpoint-might-be-post","label":"9) Why an /authorize endpoint might be POST"},{"id":"10-mcp-authenticating-mcp-servers-and-forwarding-headers","label":"10) MCP: authenticating MCP servers and forwarding headers"},{"id":"11-sql-server-auth-username-password-vs-windows-sso","label":"11) SQL Server auth: username/password vs Windows/SSO"},{"id":"12-practical-security-checklist","label":"12) Practical security checklist"},{"id":"putting-it-all-together-one-page-mental-model","label":"Putting it all together (one-page mental model)"}],"html":"<header>\\n  <div class=\\"wrap\\">\\n    \\n    <p class=\\"muted\\">\\n      A practical, end-to-end guide to: API keys, Bearer tokens, OAuth/OIDC (PKCE), JWT vs opaque tokens (introspection),\\n      Google (Gmail) login verification with JWKS, and how this ties into MCP servers and SQL Server access.\\n    </p>\\n\\n    <div class=\\"toc\\">\\n      <strong>Contents</strong>\\n      <ul>\\n        <li><a href=\\"#big-picture\\">1) Big picture: who talks to whom?</a></li>\\n        <li><a href=\\"#bearer\\">2) Bearer tokens (Authorization: Bearer ...)</a></li>\\n        <li><a href=\\"#api-keys\\">3) API keys: when they fit (and when they don\u2019t)</a></li>\\n        <li><a href=\\"#opaque-vs-jwt\\">4) Opaque vs JWT access tokens</a></li>\\n        <li><a href=\\"#introspection\\">5) Opaque tokens: introspection flow</a></li>\\n        <li><a href=\\"#jwks\\">6) JWT tokens: JWKS + public key caching</a></li>\\n        <li><a href=\\"#google-oidc\\">7) \u201cGmail authenticator\u201d: Google OIDC login</a></li>\\n        <li><a href=\\"#pkce\\">8) PKCE: why it exists and when you use it</a></li>\\n        <li><a href=\\"#authorize-post\\">9) Why an /authorize endpoint might be POST</a></li>\\n        <li><a href=\\"#mcp\\">10) MCP: authenticating MCP servers and forwarding headers</a></li>\\n        <li><a href=\\"#sql-auth\\">11) SQL Server auth: username/password vs Windows/SSO</a></li>\\n        <li><a href=\\"#security\\">12) Practical security checklist</a></li>\\n      </ul>\\n    </div>\\n  </div>\\n</header>\\n\\n<main class=\\"wrap\\">\\n\\n  <section id=\\"big-picture\\">\\n    <h2 id=\\"1-big-picture-who-talks-to-whom\\">1) Big picture: who talks to whom?</h2>\\n    <p>\\n      Almost every authentication setup can be described with three roles:\\n    </p>\\n    <ul>\\n      <li><strong>Client</strong>: your app, script, frontend, or service making requests</li>\\n      <li><strong>Resource Server</strong>: the API you want to call (your MCP server, your web API, etc.)</li>\\n      <li><strong>Authorization Server / Identity Provider</strong>: issues tokens (your auth server, Google, Entra ID, etc.)</li>\\n    </ul>\\n\\n    <div class=\\"card\\">\\n      <div class=\\"diagram\\">\\n        (A) Client authenticates with Auth Server  \u2192  gets token<br>\\n        (B) Client calls Resource Server           \u2192  sends token in headers<br>\\n        (C) Resource Server validates token        \u2192  grants/denies access\\n      </div>\\n    </div>\\n\\n    <div class=\\"callout warn\\">\\n      <strong>Critical idea:</strong> A <em>bearer</em> token is like a \u201ckeycard\u201d. Whoever holds it can use it.\\n      So you must protect it in transit and at rest (HTTPS, secure storage). (RFC 6750) \\n      <span class=\\"ref\\">Reference: RFC 6750 Bearer Token Usage.</span>\\n    </div>\\n    <div class=\\"ref\\">\\n      Sources: <a href=\\"https://datatracker.ietf.org/doc/html/rfc6750\\" target=\\"_blank\\" rel=\\"noopener\\">RFC 6750 Bearer Token Usage</a>\\n      and general OAuth usage.\\n    </div>\\n  </section>\\n\\n  <section id=\\"bearer\\">\\n    <h2 id=\\"2-bearer-tokens-authorization-bearer\\">2) Bearer tokens (Authorization: Bearer ...)</h2>\\n\\n    <p>\\n      A bearer token is sent on every request to a protected API using an HTTP header:\\n      <code class=\\"inline\\">Authorization: Bearer &lt;token&gt;</code>.\\n    </p>\\n    <div class=\\"ref\\">\\n      Source: <a href=\\"https://datatracker.ietf.org/doc/html/rfc6750\\" target=\\"_blank\\" rel=\\"noopener\\">RFC 6750 bearer token scheme</a>.\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <strong>What the server does with a bearer token</strong>\\n      <ol>\\n        <li>Extract token from the <code class=\\"inline\\">Authorization</code> header</li>\\n        <li>Validate it (either by introspection call or signature verification)</li>\\n        <li>Check claims/scopes/roles (authorization)</li>\\n        <li>Allow or deny the request</li>\\n      </ol>\\n    </div>\\n\\n    <div class=\\"callout ok\\">\\n      <strong>Why this is common:</strong> it works the same for browsers, mobile, services, and \u201cagent\u201d calls.\\n    </div>\\n  </section>\\n\\n  <section id=\\"api-keys\\">\\n    <h2 id=\\"3-api-keys-when-they-fit-and-when-they-don-t\\">3) API keys: when they fit (and when they don\u2019t)</h2>\\n\\n    <p>\\n      An \u201cauth key\u201d often means an <strong>API key</strong>: a static secret like <code class=\\"inline\\">X-API-Key: ...</code>.\\n      It\u2019s simple, but it\u2019s usually a <em>service identity</em>, not a <em>user identity</em>.\\n    </p>\\n\\n    <table>\\n      <thead>\\n        <tr><th>Approach</th><th>Good for</th><th>Weakness</th></tr>\\n      </thead>\\n      <tbody>\\n        <tr>\\n          <td><strong>API key (static)</strong></td>\\n          <td>Internal service-to-service, quick prototypes</td>\\n          <td>Often long-lived; hard per-user auth; higher blast radius if leaked</td>\\n        </tr>\\n        <tr>\\n          <td><strong>Token (short-lived)</strong></td>\\n          <td>User-level identity, scopes, auditability, safer rotation</td>\\n          <td>More moving parts (issuer + validation)</td>\\n        </tr>\\n      </tbody>\\n    </table>\\n\\n    <div class=\\"callout\\">\\n      <strong>Common hybrid pattern:</strong> use an API key to authenticate to an auth server, then exchange it for a short-lived bearer token.\\n    </div>\\n  </section>\\n\\n  <section id=\\"opaque-vs-jwt\\">\\n    <h2 id=\\"4-opaque-vs-jwt-access-tokens\\">4) Opaque vs JWT access tokens</h2>\\n\\n    <p>\\n      Bearer tokens can be:\\n      <strong>opaque strings</strong> (random-looking) or <strong>structured JWTs</strong>.\\n      The difference is how the resource server validates them.\\n    </p>\\n\\n    <table>\\n      <thead>\\n        <tr><th>Token type</th><th>What it looks like</th><th>How server validates</th><th>Tradeoff</th></tr>\\n      </thead>\\n      <tbody>\\n        <tr>\\n          <td><strong>Opaque token</strong></td>\\n          <td>Random string</td>\\n          <td>Call auth server (introspection)</td>\\n          <td>Easy revocation, but adds network hop</td>\\n        </tr>\\n        <tr>\\n          <td><strong>JWT</strong></td>\\n          <td><code class=\\"inline\\">header.payload.signature</code></td>\\n          <td>Verify signature locally using public key</td>\\n          <td>No hop per request, but revocation is harder (use short expiry/rotation)</td>\\n        </tr>\\n      </tbody>\\n    </table>\\n\\n    <div class=\\"ref\\">\\n      Sources: bearer tokens can be opaque or structured; introspection is defined by\\n      <a href=\\"https://datatracker.ietf.org/doc/html/rfc7662\\" target=\\"_blank\\" rel=\\"noopener\\">RFC 7662</a>.\\n    </div>\\n  </section>\\n\\n  <section id=\\"introspection\\">\\n    <h2 id=\\"5-opaque-tokens-introspection-flow-client-server-both-talk-to-auth-server\\">5) Opaque tokens: introspection flow (client + server both talk to auth server)</h2>\\n\\n    <p>\\n      This is the \u201cboth client and server access auth server\u201d pattern you asked about:\\n    </p>\\n\\n    <div class=\\"card\\">\\n      <div class=\\"diagram\\">\\n        1) Client \u2192 Auth Server: POST /token (login / credentials) \u2192 gets opaque access_token<br>\\n        2) Client \u2192 Resource Server: Authorization: Bearer access_token<br>\\n        3) Resource Server \u2192 Auth Server: POST /introspect (is token active? scopes?)<br>\\n        4) Resource Server \u2192 Client: allow/deny\\n      </div>\\n    </div>\\n\\n    <div class=\\"ref\\">\\n      Token introspection spec: resource server queries auth server about token state\\n      (<a href=\\"https://datatracker.ietf.org/doc/html/rfc7662\\" target=\\"_blank\\" rel=\\"noopener\\">RFC 7662</a>).\\n    </div>\\n\\n    <h3 id=\\"example-endpoints-like-our-demo\\">Example endpoints (like our demo)</h3>\\n    <pre><code># Auth server:\\nPOST /token        -&gt; returns {\\"access_token\\": \\"...\\", \\"expires_in\\": 3600}\\nPOST /introspect   -&gt; returns {\\"active\\": true, \\"sub\\": \\"demo\\", \\"scope\\": \\"sql:read\\"}</code></pre>\\n\\n    <div class=\\"callout ok\\">\\n      <strong>Why people choose this:</strong> easy centralized revocation and policy checks (auth server is source of truth).\\n    </div>\\n\\n    <div class=\\"callout warn\\">\\n      <strong>Production tip:</strong> add caching at the resource server (cache introspection results briefly) to reduce auth server load.\\n    </div>\\n  </section>\\n\\n  <section id=\\"jwks\\">\\n    <h2 id=\\"6-jwt-tokens-jwks-public-key-caching-server-keeps-the-public-key\\">6) JWT tokens: JWKS + public key caching (server \u201ckeeps the public key\u201d)</h2>\\n\\n    <p>\\n      When the access token is a JWT, the server can validate it locally using a public key.\\n      But the key might rotate, so the server usually downloads keys from a JWKS endpoint.\\n    </p>\\n\\n    <div class=\\"card\\">\\n      <div class=\\"diagram\\">\\n        Startup (or periodic):<br>\\n        1) GET /.well-known/openid-configuration  \u2192 find jwks_uri<br>\\n        2) GET jwks_uri                          \u2192 cache public keys keyed by \\"kid\\"<br><br>\\n        Per request:<br>\\n        3) Read JWT header.kid \u2192 pick matching public key<br>\\n        4) Verify signature + validate claims (iss, aud, exp)\\n      </div>\\n    </div>\\n\\n    <div class=\\"ref\\">\\n      OIDC Discovery defines the well-known configuration and includes <code class=\\"inline\\">jwks_uri</code>; verification relies on keys.\\n      See the <a href=\\"https://openid.net/specs/openid-connect-discovery-1_0.html\\">OpenID Connect Discovery specification</a>.\\n    </div>\\n\\n    <h3 id=\\"why-this-is-faster-than-introspection\\">Why this is faster than introspection</h3>\\n    <ul>\\n      <li>No network call to auth server per request (after keys are cached)</li>\\n      <li>Works even if auth server is temporarily down (until keys expire/rotate)</li>\\n    </ul>\\n\\n    <div class=\\"callout warn\\">\\n      <strong>Tradeoff:</strong> immediate revocation is harder. Typical mitigations: short token lifetimes + key rotation + occasional back-channel checks.\\n    </div>\\n  </section>\\n\\n  <section id=\\"google-oidc\\">\\n    <h2 id=\\"7-gmail-authenticator-google-oidc-login-client-still-talks-to-google\\">7) \u201cGmail authenticator\u201d: Google OIDC login (client still talks to Google)</h2>\\n\\n    <p>\\n      If \u201cauth server is Gmail\u201d means \u201cusers sign in with their Google account\u201d, you\u2019re using\\n      <strong>OpenID Connect (OIDC) on top of OAuth 2.0</strong>. Google issues an <strong>ID token</strong> (a signed JWT) and optionally access tokens.\\n    </p>\\n\\n    <div class=\\"ref\\">Google documents its OpenID Connect implementation and server-side token verification in the <a href=\\"https://developers.google.com/identity/openid-connect/openid-connect\\">Google Identity OIDC guide</a>.</div>\\n\\n    <div class=\\"callout\\">\\n      <strong>Key point you asked:</strong> even if your server caches Google\u2019s public keys, the <em>client still must talk to Google</em> to obtain the token (login/consent).\\n      Caching keys only removes server\u2192Google calls on each request.\\n    </div>\\n\\n    <h3 id=\\"what-your-resource-server-validates-minimum\\">What your resource server validates (minimum)</h3>\\n    <ul>\\n      <li><code class=\\"inline\\">iss</code> (issuer) is Google</li>\\n      <li><code class=\\"inline\\">aud</code> (audience) matches your Google OAuth client ID</li>\\n      <li><code class=\\"inline\\">exp</code> not expired</li>\\n      <li>signature matches a Google public key from JWKS</li>\\n    </ul>\\n\\n    <div class=\\"ref\\">OIDC Core defines claims such as <code class=\\"inline\\">iss</code>, <code class=\\"inline\\">aud</code>, and <code class=\\"inline\\">exp</code>; see the <a href=\\"https://openid.net/specs/openid-connect-core-1_0.html\\">OpenID Connect Core specification</a>.</div>\\n  </section>\\n\\n  <section id=\\"pkce\\">\\n    <h2 id=\\"8-pkce-why-it-exists-and-when-you-use-it\\">8) PKCE: why it exists and when you use it</h2>\\n\\n    <p>\\n      <strong>PKCE</strong> (Proof Key for Code Exchange) protects the OAuth authorization code flow against code interception attacks\\n      for <em>public clients</em> (mobile apps, SPAs, desktop apps). (RFC 7636)\\n    </p>\\n    <div class=\\"ref\\">PKCE is defined in <a href=\\"https://datatracker.ietf.org/doc/html/rfc7636\\">RFC 7636</a>.</div>\\n\\n    <div class=\\"card\\">\\n      <div class=\\"diagram\\">\\n        1) Client generates code_verifier (secret) and code_challenge (hash)<br>\\n        2) Client \u2192 /authorize includes code_challenge<br>\\n        3) Client receives authorization code<br>\\n        4) Client \u2192 /token sends authorization code + code_verifier<br>\\n        5) Auth server checks verifier matches challenge, then issues tokens\\n      </div>\\n    </div>\\n\\n    <div class=\\"callout ok\\">\\n      <strong>Modern direction:</strong> The active OAuth 2.1 Internet-Draft\\n      requires PKCE for authorization-code clients. It is a draft, not a\\n      published RFC; use RFC 9700 as the finalized OAuth 2.0 security\\n      best-current-practice baseline.\\n    </div>\\n    <div class=\\"ref\\">See the <a href=\\"https://datatracker.ietf.org/doc/draft-ietf-oauth-v2-1/\\">active OAuth 2.1 Internet-Draft</a> and <a href=\\"https://datatracker.ietf.org/doc/html/rfc9700\\">RFC 9700: OAuth 2.0 Security Best Current Practice</a>.</div>\\n  </section>\\n\\n  <section id=\\"authorize-post\\">\\n    <h2 id=\\"9-why-an-authorize-endpoint-might-be-post\\">9) Why an <code class=\\"inline\\">/authorize</code> endpoint might be POST</h2>\\n\\n    <p>\\n      In the classic OAuth/OIDC web flow, <code class=\\"inline\\">/authorize</code> is often reached via a browser navigation\\n      (commonly a GET with query parameters). But you may see POST in practice because:\\n    </p>\\n\\n    <ul>\\n      <li><strong>Form submissions</strong>: login pages submit credentials and consent forms via POST, and then the server continues the authorization flow.</li>\\n      <li><strong>Reducing sensitive data in URLs</strong>: some systems avoid putting large or sensitive request data in query strings.</li>\\n      <li><strong>OIDC response mode \u201cform_post\u201d</strong>: the authorization response can be returned to the client via an HTTP form POST.</li>\\n    </ul>\\n\\n    <div class=\\"ref\\">OIDC Core defines the overall authorization behavior; response modes such as <code class=\\"inline\\">form_post</code> are specified separately by OpenID.</div>\\n\\n    <div class=\\"callout warn\\">\\n      <strong>Important:</strong> Whether your <code class=\\"inline\\">/authorize</code> is GET or POST is a design choice / framework detail.\\n      The security requirements (PKCE, redirect URI validation, HTTPS, etc.) matter much more than the verb itself.\\n    </div>\\n  </section>\\n\\n  <section id=\\"mcp\\">\\n    <h2 id=\\"10-mcp-authenticating-mcp-servers-and-forwarding-headers\\">10) MCP: authenticating MCP servers and forwarding headers</h2>\\n\\n    <p>\\n      For MCP, the same authentication patterns apply: protect your MCP server and require a token (or API key) on its HTTP endpoint.\\n      When an LLM (via OpenAI\u2019s tool integration) calls your remote MCP server, you typically pass credentials in HTTP headers.\\n    </p>\\n\\n    <div class=\\"card\\">\\n      <strong>What you do in practice</strong>\\n      <ol>\\n        <li>Your client obtains a token (from your auth server, Google OIDC, etc.)</li>\\n        <li>Your client configures the MCP tool with <strong>headers</strong> containing that token</li>\\n        <li>The MCP server middleware checks <code class=\\"inline\\">Authorization: Bearer ...</code> on every request</li>\\n      </ol>\\n    </div>\\n\\n    <div class=\\"ref\\">\\n      OpenAI docs cover MCP integration, tool filtering with <code class=\\"inline\\">allowed_tools</code>, and MCP tool usage via the Responses API.\\n    </div>\\n\\n    <h3 id=\\"example-bearer-token-on-mcp-calls\\">Example: bearer token on MCP calls</h3>\\n    <pre><code># Client sets headers when connecting:\\nheaders = {\\"Authorization\\": f\\"Bearer {token}\\"}\\n\\n# MCP server checks Authorization header for every /mcp request\\n# (then validates via introspection or JWT verification)</code></pre>\\n\\n    <div class=\\"callout ok\\">\\n      <strong>Safety practice you discussed:</strong> avoid passing secrets as tool arguments; prefer headers or OAuth.\\n      Also restrict which tools the model can use (e.g., read-only) with <code class=\\"inline\\">allowed_tools</code>.\\n    </div>\\n    <div class=\\"ref\\">OpenAI MCP tool guidance covers filtering tools with <code class=\\"inline\\">allowed_tools</code>.</div>\\n  </section>\\n\\n  <section id=\\"sql-auth\\">\\n    <h2 id=\\"11-sql-server-auth-username-password-vs-windows-sso\\">11) SQL Server auth: username/password vs Windows/SSO</h2>\\n\\n    <p>\\n      This is separate from your API/MCP authentication. This is how your software authenticates to the database itself.\\n      SQL Server commonly supports:\\n    </p>\\n\\n    <ul>\\n      <li><strong>Windows Authentication</strong> (Integrated / Active Directory): the OS/AD vouches for the identity; SQL Server doesn\u2019t handle passwords directly.</li>\\n      <li><strong>SQL Server Authentication</strong>: database-level username/password (\u201cSQL login\u201d).</li>\\n    </ul>\\n\\n    <div class=\\"ref\\">Microsoft Learn explains SQL Server authentication modes and when to choose Windows authentication or SQL Server authentication.</div>\\n\\n    <h3 id=\\"how-it-looks-in-connection-configuration\\">How it looks in connection configuration</h3>\\n    <pre><code># SQL authentication (username/password in connection string)\\nDRIVER={ODBC Driver 18 for SQL Server};\\nSERVER=host,1433;\\nDATABASE=MyDb;\\nUID=${DB_USER};\\nPWD=${DB_PASSWORD_FROM_SECRET_MANAGER};\\nEncrypt=yes;\\nTrustServerCertificate=no;\\n\\n# Windows integrated authentication (varies by environment)\\n# Often includes Integrated Security / Trusted_Connection\\n# DRIVER=...;SERVER=...;DATABASE=...;Trusted_Connection=yes;</code></pre>\\n\\n    <div class=\\"callout ok\\">\\n      <strong>Industry standard:</strong> prefer managed identity / Active Directory authentication where possible.\\n      If you must use SQL username/password, store the password in a secret manager, rotate it, require encrypted transport,\\n      and validate the server certificate instead of using <code class=\\"inline\\">TrustServerCertificate=yes</code>.\\n    </div>\\n\\n    <div class=\\"callout warn\\">\\n      <strong>Don\u2019t confuse the layers:</strong><br>\\n      Your API/MCP auth controls \u201cwho can call the server\u201d. DB auth controls \u201cwhat the server process is allowed to do in the database\u201d.\\n      In production, you usually use a service identity with least privilege for DB access.\\n    </div>\\n  </section>\\n\\n  <section id=\\"security\\">\\n    <h2 id=\\"12-practical-security-checklist\\">12) Practical security checklist</h2>\\n\\n    <div class=\\"card\\">\\n      <strong>Transport &amp; storage</strong>\\n      <ul>\\n        <li>Always use HTTPS/TLS for bearer tokens (possession = access). (RFC 6750)</li>\\n        <li>Don\u2019t log tokens; avoid putting them in URLs; store securely.</li>\\n      </ul>\\n      <div class=\\"ref\\">Bearer token security considerations are covered in <a href=\\"https://datatracker.ietf.org/doc/html/rfc6750\\">RFC 6750</a>.</div>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <strong>Token validation</strong>\\n      <ul>\\n        <li>Opaque tokens: implement introspection (RFC 7662) and consider caching.</li>\\n        <li>JWT tokens: verify signature + claims; fetch JWKS via OIDC discovery; refresh on unknown <code class=\\"inline\\">kid</code>.</li>\\n        <li>Always validate <code class=\\"inline\\">aud</code> and <code class=\\"inline\\">iss</code> for OIDC tokens.</li>\\n      </ul>\\n      <div class=\\"ref\\">Token introspection is defined in <a href=\\"https://datatracker.ietf.org/doc/html/rfc7662\\">RFC 7662</a>; JWT validation commonly combines OIDC Discovery and OIDC Core.</div>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <strong>OAuth/OIDC hygiene</strong>\\n      <ul>\\n        <li>Use PKCE for authorization-code clients. (RFC 7636; RFC 9700)</li>\\n        <li>Use exact redirect URI matching and avoid the implicit grant. (RFC 9700)</li>\\n        <li>Do not use the resource-owner password credentials grant; prefer browser-based authorization or workload credentials appropriate to the caller.</li>\\n      </ul>\\n      <div class=\\"ref\\">See <a href=\\"https://datatracker.ietf.org/doc/html/rfc7636\\">RFC 7636</a> for PKCE, <a href=\\"https://datatracker.ietf.org/doc/html/rfc9700\\">RFC 9700</a> for the finalized security BCP, and the OAuth 2.1 draft for consolidation work still in progress.</div>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <strong>MCP-specific hygiene</strong>\\n      <ul>\\n        <li>Use least-privilege tool exposure (e.g., read-only tools) via <code class=\\"inline\\">allowed_tools</code>.</li>\\n        <li>Prefer headers/OAuth rather than passing secrets in tool arguments.</li>\\n      </ul>\\n      <div class=\\"ref\\">OpenAI\u2019s MCP tool guidance covers tool filtering and MCP tool usage.</div>\\n    </div>\\n  </section>\\n\\n  <div class=\\"hr\\"></div>\\n  <section>\\n    <h2 id=\\"putting-it-all-together-one-page-mental-model\\">Putting it all together (one-page mental model)</h2>\\n\\n    <div class=\\"card\\">\\n      <div class=\\"diagram\\">\\n        Your user logs in (or your service authenticates) \u2192 gets a token (Bearer)<br>\\n        Your app calls your protected API/MCP server with Authorization: Bearer ...<br>\\n        Your API validates token either via RFC 7662 introspection (opaque) or JWT verification (JWKS)<br>\\n        Your API uses DB credentials (separate layer) to query SQL Server<br>\\n        Your API returns response\\n      </div>\\n    </div>\\n\\n    <div class=\\"tr-note\\">\\n      <strong>Implementation decision</strong>\\n      Choose the validation path from both token format and caller type:\\n      opaque tokens require introspection; JWT access tokens use issuer\\n      metadata and JWKS; Google OIDC identifies the user but the API must still\\n      receive an access token intended for its audience. Browser and mobile\\n      public clients use Authorization Code with PKCE, while backend services\\n      use an approved workload flow or token exchange.\\n    </div>\\n  </section>\\n\\n</main>"}'),c={title:"Authentication: API Keys, Bearer Tokens, OAuth/OIDC, JWTs, and Opaque Tokens",slug:"/part2-backend-platform-security/09-authentication-deep-dive",description:"A practical, end-to-end guide to: API keys, Bearer tokens, OAuth/OIDC (PKCE), JWT vs opaque tokens (introspection), Google (Gmail) login verification with JWKS, and how this ties into MCP servers and SQL Server access.",sidebar_label:"10. Authentication deep dive",pagination_label:"10. Authentication deep dive",hide_title:!0,hide_table_of_contents:!0},l=void 0,d={},h=[];function u(e){return(0,o.jsx)(s.A,{content:a})}function p(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(u,{...e})}):u()}}}]);